export type SearchSettings = {
	/**
	 *  Folders whose contents never show up in file results: a folder name
	 *  ("node_modules") or a partial path ("AppData\Local\Temp").
	 */
	exclusions: string[],
	/**
	 *  Folders the built-in file index covers when Everything isn't running.
	 *  `~` is your user folder.
	 */
	index_folders: string[],
	max_results: number,
};

/**
 *  Fuller results for search `seq`, from providers that missed the
 *  per-keystroke budget. Replaces that search's list.
 */
export type SearchUpdated = {
	seq: number,
	items: ResultItem[],
};

export type Settings = {
	version: number,
	hotkeys: HotkeySettings,
	ai: AiSettings,
	search: SearchSettings,
	general: GeneralSettings,
	calculator: CalcSettings,
	quicklinks: QuicklinkSettings,
	emoji: EmojiSettings,
	clipboard: ClipboardSettings,
	snippets: SnippetSettings,
	scripts: ScriptSettings,
	updates: UpdateSettings,
	system: SystemSettings,
	color_picker: ColorSettings,
	history: HistorySettings,
	ai_commands: AiCommandSettings,
	google: GoogleSettings,
	mcp: McpSettings,
	appearance: AppearanceSettings,
};

/**  The settings changed outside the menu and the new ones are in use. */
export type SettingsChanged = {
	settings: Settings,
};

/**  Where settings are kept, for the Advanced section. */
export type SettingsFolder = {
	/**  The folder `settings.toml` is read from now. */
	folder: string,
	is_default: boolean,
	default_folder: string,
	/**  This PC's own settings (`settings.local.toml`). */
	local_file: string,
	/**
	 *  A chosen folder that isn't there now; the default one is used
	 *  until it is.
	 */
	missing: string | null,
	/**
	 *  `settings.toml` couldn't be read; only this PC's settings are saved
	 *  until it can be.
	 */
	unreadable: string | null,
	/**
	 *  OneDrive's folder for the settings, when OneDrive is set up on this
	 *  PC and it isn't the folder in use.
	 */
	suggestion: FolderCheck | null,
};

/**  The result of saving settings. */
export type SettingsSaved = {
	/**
	 *  Index folders or exclusions differ from what the running index uses;
	 *  they apply after a restart.
	 */
	restart_needed: boolean,
};

/**  Open the settings menu (from the tray). */
export type ShowSettings = null;

/**  Skin tone for emoji that have them. `None` is the default yellow. */
export type SkinTone = "none" | "light" | "medium_light" | "medium" | "medium_dark" | "dark";

export type Snippet = {
	name: string,
	/**  Typed to find or expand it, e.g. ";sig". May be empty. */
	keyword: string,
	/**  The text, with optional placeholders. */
	text: string,
};

export type SnippetSettings = {
	/**  Snippets show up in search. */
	enabled: boolean,
	items: Snippet[],
	/**  Typing a keyword in any app replaces it with the snippet. */
	expand_as_you_type: boolean,
	/**
	 *  Only keywords starting with this expand as you type, so ordinary
	 *  words never do.
	 */
	trigger: string,
};

export type SystemSettings = {
	/**  System commands and Settings pages in search. */
	enabled: boolean,
	/**
	 *  Restart, shut down, sign out, hibernate and emptying the Recycle Bin
	 *  ask in the footer first; Enter again runs them.
	 */
	confirm: boolean,
};

/**  Shown in the footer for a few seconds. */
export type Toast = {
	level: ToastLevel,
	message: string,
};

export type ToastLevel = "info" | "error";

export type ToolState = "running" | "ok" | "failed";

/**  What the updater is doing. Shown in the settings menu and search. */
export type UpdatePhase = 
/**  This build has no public key to check updates with. */
{ state: "not_set_up" } | 
/**  Not checked yet since the app started. */
{ state: "idle" } | { state: "checking" } | { state: "up_to_date" } | 
/**  `percent` once the download's size is known. */
{ state: "downloading"; version: string; percent: number | null } | 
/**  Downloaded and its signature checked: installs on restart. */
{ state: "ready"; version: string } | 
/**  The installer is starting; the app is about to close. */
{ state: "installing"; version: string } | 
/**  A check or download failed; `message` says which and why. */
{ state: "failed"; message: string };

export type UpdateSettings = {
	/**
	 *  Look for a new version a minute after start and every 6 hours, and
	 *  download it in the background. Installing always waits for you.
	 */
	check_automatically: boolean,
};

/**  Where updating stands, for the settings menu. */
export type UpdateStatus = {
	/**  The running version ("0.1.0"). */
	current_version: string,
	phase: UpdatePhase,
	/**  The phase in a few words ("Downloading v0.2.0… 40%"). */
	summary: string,
	/**  When a check last got an answer on this PC (seconds since 1970). */
	last_checked: number | null,
	/**
	 *  Goes up with every change, so the UI can tell an answer that
	 *  arrives late (a command's reply after newer events) and ignore it.
	 */
	revision: number,
};

/**
 *  Sent whenever `UpdateStatus` changes (a few times a second at most
 *  while downloading).
 */
export type UpdateStatusChanged = {
	status: UpdateStatus,
};

/**  The Windows key override, for the settings menu. */
export type WinKeyStatus = {
	enabled: boolean,
	/**  The keyboard hook is installed. */
	running: boolean,
	/**  Seconds since the hook last saw a Windows key press. */
	last_seen_secs: number | null,
	/**
	 *  Times Start opened anyway after a tap and was closed again, since the
	 *  launcher started.
	 */
	start_closed: number,
	/**
	 *  Windows key presses and releases the hook answered late (Windows may
	 *  have used the key anyway), since the launcher started.
	 */
	late_answers: number,
	/**
	 *  `LowLevelHooksTimeout` in ms, if set (otherwise Windows' default,
	 *  about 300 ms).
	 */
	hook_timeout_ms: number | null,
	/**
	 *  The timeout changed since the launcher started, so it applies after
	 *  signing out.
	 */
	hook_timeout_pending: boolean,
};

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

type EventEmit<T> = [T] extends [null] ? () => Promise<void> : (payload: T) => Promise<void>;

function makeEvent<T>(name: string, serialize?: (payload: T) => unknown, deserialize?: (payload: any) => T) {
    const mapEvent = (cb: __TAURI_EVENT.EventCallback<T>) => (event: __TAURI_EVENT.Event<any>) => cb({ ...event, payload: deserialize ? deserialize(event.payload) : event.payload });
    const mapPayload = (payload: T) => serialize ? serialize(payload) : payload;

    const base = {
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.once(name, mapEvent(cb)),
        emit: ((payload: T) => __TAURI_EVENT.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    };

    const fn = (target: import("@tauri-apps/api/webview").Webview | import("@tauri-apps/api/window").Window) => ({
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => target.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => target.once(name, mapEvent(cb)),
        emit: ((payload: T) => target.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    });

    return Object.assign(fn, base);
}

